-- 0049_lab12_base64_syntax_drill.sql: add 4 syntax-drill steps (certutil
-- -encode/-decode on Windows, base64 -w0/-d on Linux) to the existing
-- "Lab 12 -- File transfer & pivoting/tunneling" card, per explicit user
-- request to practice these commands for memorization (encode/decode a
-- binary file to/from a text-safe form). Pure syntax drill, no attack
-- framing -- consistent with the other file-transfer steps already in
-- this lab (wget, chisel, certutil -urlcache).

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Trên máy attacker Windows, encode file note.bin sang dạng base64 (chuỗi text an toàn để dán qua một kênh chỉ gõ được lệnh text), lưu ra note.b64.", "hint": "certutil -encode note.bin note.b64", "patterns": ["certutil\\s+-encode\\s+note\\.bin\\s+note\\.b64"], "explanation": "certutil -encode có sẵn trên mọi máy Windows, không cần cài thêm — hữu ích để chuyển file nhị phân thành text khi không tải file trực tiếp qua mạng được."}, {"prompt": "Trên máy đích đã có sẵn file note.b64 (được dán/copy từ máy attacker). Decode ngược lại thành file nhị phân gốc note.bin.", "hint": "certutil -decode note.b64 note.bin", "patterns": ["certutil\\s+-decode\\s+note\\.b64\\s+note\\.bin"], "explanation": "certutil -decode là thao tác đảo ngược của -encode, khôi phục đúng nội dung nhị phân ban đầu."}, {"prompt": "Hoàn thiện lệnh base64 trên Linux để encode file note.bin, xuất ra MỘT DÒNG duy nhất (không xuống dòng) để dễ copy-paste, lưu ra note.b64: base64 ____ note.bin > note.b64", "hint": "base64 -w0 note.bin > note.b64", "patterns": ["base64\\s+-w\\s*0\\s+note\\.bin\\s*>\\s*note\\.b64"], "explanation": "-w0 (wrap=0) tắt việc tự động xuống dòng mỗi 76 ký tự (mặc định của GNU base64) — cần thiết khi bạn sẽ dán chuỗi này qua một dòng lệnh duy nhất."}, {"prompt": "Hoàn thiện lệnh base64 trên Linux để decode ngược file note.b64 về lại note.bin: base64 ____ note.b64 > note.bin", "hint": "base64 -d note.b64 > note.bin", "patterns": ["base64\\s+-d\\s+note\\.b64\\s*>\\s*note\\.bin"], "explanation": "-d (decode) là cờ ngược lại của bước encode — luôn đi kèm redirect > ra file đích."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 12 — File transfer & pivoting/tunneling';
